reg=good(admin,'/events/'+eid+'/registrations','POST',{});request=good(admin,'/governance/requests/'+reg['approvalRequestId'])['request'];code,b=admin.req('/governance/requests/'+request['id']+'/decisions','POST',{'decision':'Approve','comment':'Self review','version':request['version']});check('registration approver cannot approve their own seat',code==403 and 'own' in b['detail'])
