sql(f'UPDATE "EventStaff" SET "EndsAt"=now()-interval \'1 second\' WHERE "EventId"=\'{eid}\' AND "PersonId"=\'{person}\';UPDATE "EventInvitations" SET "SendAt"=now()-interval \'1 second\' WHERE "EventId"=\'{eid}\'');deadline=time.monotonic()+12
