check('signed-in nonmember cannot bypass guests-disabled policy',manager.req('/events/'+fid+'/registrations','POST',{})[0]==403)
sql(f'UPDATE "Events" SET "AllowGuests"=true WHERE "Id"=\'{fid}\'');foreignreg=good(manager,'/events/'+fid+'/registrations','POST',{});check('signed-in external participant is classified as a guest',foreignreg['membershipId'] is None and foreignreg['category']=='Guest');foreignstats=good(admin,'/events/'+fid+'/analytics');check('guest metrics follow membership rather than account identity',foreignstats['guests']==1 and foreignstats['members']==0)
