import concurrent.futures
concurrent_event=good(admin,'/events','POST',{**base,'orgId':other['orgId'],'typeId':otype,'title':'Session race '+tag,'registrationApproval':False});ceid=concurrent_event['id'];session_input={'title':'Concurrent session','room':'Single room','speaker':'Single speaker','startsAt':at(0),'endsAt':at(1),'capacity':10}
